{
  "name": "flaky-tests-demo",
  "private": true,
  "type": "module",
  "scripts": {
    "baseline": "playwright test tests/before.spec.ts --update-snapshots --retries=10 --workers=1 --reporter=dot",
    "before": "playwright test tests/before.spec.ts --repeat-each=20 --workers=1",
    "after": "playwright test tests/after.spec.ts --repeat-each=20 --workers=1",
    "demo": "playwright install chromium && npm run -s baseline > /dev/null; npm run -s before; npm run -s after"
  },
  "devDependencies": {
    "@playwright/test": "1.56.1"
  }
}

import { test, expect } from "@playwright/test";

test("checkout places the order", async ({ page, request }) => {
  await page.goto("/checkout");
  const charge = page.waitForResponse((r) => r.url().endsWith("/api/charge"));
  await page.getByRole("button", { name: "Pay" }).click();

  const res = await charge; // waits for the real response, however long it takes
  expect(res.status()).toBe(200);
  const { orderId } = await res.json();

  const order = await request.get(`/api/orders/${orderId}`);
  expect(order.ok()).toBe(true);
  expect((await order.json()).status).toBe("paid");
});

import { test, expect } from "@playwright/test";

test("checkout places the order", async ({ page }) => {
  await page.goto("/checkout");
  await page.getByRole("button", { name: "Pay" }).click();
  await page.waitForTimeout(1000); // "long enough" on the laptop that wrote it
  expect(await page.locator(".spinner").isVisible()).toBe(false);
  await expect(page).toHaveScreenshot("order-placed.png");
});

import { defineConfig } from "@playwright/test";
export default defineConfig({
  use: { baseURL: "http://localhost:4317" },
  // One baseline per machine: fonts render differently across operating systems.
  snapshotPathTemplate: "{testDir}/__screenshots__/{arg}{ext}",
  webServer: { command: "node server.mjs", url: "http://localhost:4317/checkout", reuseExistingServer: true },
});

